(function() {
    'use strict';

    class VentureArmAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'VentureArm CVC Simulation';
            this.version = '1.1.0';
            // Per-round domainState snapshots (deep copies) taken before each
            // calculateResults() mutation, so an Undo can roll domainState back
            // instead of continuing to accumulate (fixes undo double-count).
            this._snap = [];

            this.ROUNDS = [
                {
                    title: 'Round 1 — Thesis Setting & First Deployments',
                    period: 'Fund Months 1-18',
                    briefing: 'Welcome to NovaChem Ventures. You manage a $100M corporate venture capital fund for NovaChem Industries, a Fortune 500 specialty chemicals company. Your mandate: deliver both financial returns (IRR target 12%+, MOIC 1.8x+) and strategic value aligned with NovaChem 2030 priorities: (1) 50% bio-based revenue, (2) AI-driven manufacturing, (3) sustainable packaging.<br><br>You inherit three portfolio companies: <b>BioForm Materials</b> (Series A, $3.5M invested, struggling — requesting a bridge loan), <b>Spectral AI</b> (Series B, $3.8M invested, on-track for growth), and <b>CircleLoop</b> (Seed, $2M invested, early-stage sustainable packaging).<br><br>Four new deal flow companies are available. Allocate your 80 due diligence hours wisely — deeper diligence reveals critical hidden information.',
                    deals: [
                        { name: 'PolyGreen Synthesis', desc: 'Bio-based polymer platform with patented catalytic process. Pre-revenue but transformational for NovaChem 2030 bio-based strategy. High risk, high strategic alignment.', ask: 8000000, stage: 'Series A', strategicFit: 4, financialRisk: 3, sector: 'bio-based' },
                        { name: 'DataChem Analytics', desc: 'AI-powered process optimization SaaS for chemical manufacturing. $2.4M ARR, 180% YoY growth. Strong financial profile, moderate strategic fit to NovaChem manufacturing AI priority.', ask: 6000000, stage: 'Series A', strategicFit: 3, financialRisk: 1, sector: 'ai-manufacturing' },
                        { name: 'WrapSustain', desc: 'Sustainable packaging materials using agricultural waste. $800K ARR, pilot contracts with 3 FMCG companies. Directly aligned with NovaChem sustainable packaging priority.', ask: 4000000, stage: 'Seed+', strategicFit: 4, financialRisk: 2, sector: 'packaging' },
                        { name: 'Quantum Materials Lab', desc: 'Advanced materials computation platform. $5M ARR, 120% growth. Financially strong but tangential strategic relevance — could provide R&D acceleration tools.', ask: 10000000, stage: 'Series B', strategicFit: 1, financialRisk: 1, sector: 'computation' }
                    ],
                    portfolioUpdates: [
                        { name: 'BioForm Materials', status: 'struggling', note: 'Behind milestones. Requesting $1.5M bridge loan. Lead the bridge or allow third-party investor (dilution risk)?' },
                        { name: 'Spectral AI', status: 'on-track', note: 'Series B approaching. Exercise pro-rata rights ($1.75M) to maintain 12.5% ownership?' },
                        { name: 'CircleLoop', status: 'early', note: 'Pilot with NovaChem Industrial Process Solutions division showing promise. Accelerate partnership?' }
                    ],
                    events: [
                        { title: 'Competitor CVC Investment', text: 'ChemCore Capital announces a $15M investment in a startup competing directly with BioForm Materials. This validates the bio-based polymer space but creates competitive pressure. How will you respond?' },
                        { title: 'Regulatory Opportunity', text: 'The EU announces new sustainability packaging regulations effective in 24 months. This dramatically increases the addressable market for sustainable packaging companies in your pipeline.' }
                    ]
                },
                {
                    title: 'Round 2 — Portfolio Management & Mid-Course Correction',
                    period: 'Fund Months 19-36',
                    briefing: 'Eighteen months have passed. Your portfolio companies are diverging — some outperforming, some struggling, some pivoting. Four new deal flow companies arrive.<br><br><b>Critical Challenge:</b> NovaChem Performance Polymers division CEO has formally complained to the Board that NovaChem Ventures has failed to deliver actionable technology intelligence. He threatens to propose shutting down the Ventures program. You must demonstrate measurable strategic value.<br><br><b>Governance Alert:</b> Spectral AI Series B terms from GreenBridge Capital include a Right of First Offer (ROFO) clause on any acquisition — directly threatening NovaChem acquisition option value. Decide: exercise pro-rata (negotiate ROFO terms) or pass and preserve capital?',
                    deals: [
                        { name: 'CatalystAI', desc: 'Machine learning for catalyst discovery. Revolutionary approach could accelerate NovaChem R&D by 3-5 years. Early revenue ($400K ARR) but exceptional team from top research lab.', ask: 5000000, stage: 'Series A', strategicFit: 4, financialRisk: 3, sector: 'ai-manufacturing' },
                        { name: 'EcoBarrier Films', desc: 'Biodegradable barrier films for food packaging. $3.2M ARR, 150% growth. Direct competitor to CircleLoop with different technology approach.', ask: 7000000, stage: 'Series A', strategicFit: 3, financialRisk: 1, sector: 'packaging' },
                        { name: 'NanoCoat Solutions', desc: 'Anti-corrosion nanocoatings for industrial applications. $6M ARR, profitable. Strong financials but limited NovaChem 2030 alignment.', ask: 9000000, stage: 'Series B', strategicFit: 1, financialRisk: 0, sector: 'materials' },
                        { name: 'BioProcess Dynamics', desc: 'Fermentation process optimization for bio-based chemicals. Pre-revenue, deep-tech. If successful, could transform NovaChem bio-based manufacturing costs.', ask: 3000000, stage: 'Seed', strategicFit: 4, financialRisk: 4, sector: 'bio-based' }
                    ],
                    portfolioUpdates: [
                        { name: 'BioForm Materials', status: 'critical', note: 'Missed Series B milestones. Lead VC declined follow-on. Needs $2M bridge or faces shutdown in 6 months.' },
                        { name: 'Spectral AI', status: 'strong', note: 'Strong growth. GreenBridge Series B includes ROFO clause threatening acquisition optionality.' },
                        { name: 'CircleLoop', status: 'growing', note: 'NovaChem pilot generating results. Partnership acceleration could boost Strategic Value Score significantly.' }
                    ],
                    events: [
                        { title: 'Technology Disruption', text: 'A major journal publishes a breakthrough in bio-polymer synthesis that could make BioForm Materials technology obsolete in 3-5 years. Assess: write off now, hedge by investing in the disruptor, or bet on pivot capability?' },
                        { title: 'Parent Company Budget Pressure', text: 'NovaChem announces a 15% company-wide budget cut due to earnings miss. The CFO proposes reducing Ventures fund commitment by $15M. Prepare evidence-based defense of fund strategic and financial value.' }
                    ]
                },
                {
                    title: 'Round 3 — Exit Positioning & Strategic Harvest',
                    period: 'Fund Months 37-54',
                    briefing: 'Final deployment round. You are transitioning from deployment to harvest. Commit remaining capital wisely while managing the portfolio toward exit.<br><br><b>Acquisition Decision:</b> NovaChem Corporate Development proposes acquiring BioForm Materials at $45M. Advise on: exercise now vs. wait for market validation, full acquisition vs. structured earn-out, integration scope.<br><br><b>Crisis:</b> One portfolio company co-founder has departed, technology has pivoted twice without traction, and they request a third bridge round. Apply rigorous sunk cost analysis.<br><br><b>Board Presentation:</b> Prepare to defend your portfolio to the Board. Present IRR vs. 12% benchmark, MOIC vs. 1.8x target, SVS vs. 65/100 target, and narrative on strategic value delivered.',
                    deals: [
                        { name: 'GreenSynth Biologics', desc: 'Next-generation biosynthetic materials platform. $1.8M ARR, backed by top-tier VCs. Potential acquisition target for NovaChem 2030 bio-based priority.', ask: 8000000, stage: 'Series A', strategicFit: 4, financialRisk: 2, sector: 'bio-based' },
                        { name: 'SmartFactory Systems', desc: 'Industrial IoT and digital twin platform for chemical plants. $7M ARR, 90% growth. Complements AI manufacturing priority.', ask: 10000000, stage: 'Series B', strategicFit: 3, financialRisk: 1, sector: 'ai-manufacturing' },
                        { name: 'CircularChem', desc: 'Chemical recycling technology for plastic waste. Pre-revenue, pilot stage. Transformational if scalable. Aligns with sustainability and packaging priorities.', ask: 4000000, stage: 'Seed', strategicFit: 4, financialRisk: 4, sector: 'packaging' },
                        { name: 'SpectraPharm Coatings', desc: 'Specialty pharmaceutical coatings. $12M ARR, profitable, approaching exit. Minimal strategic fit but strong financial return potential.', ask: 12000000, stage: 'Series B', strategicFit: 0, financialRisk: 0, sector: 'pharma' }
                    ],
                    portfolioUpdates: [
                        { name: 'BioForm Materials', status: 'acquisition', note: 'NovaChem Corporate Development offers $45M acquisition. Exercise option or continue as portfolio company?' },
                        { name: 'Spectral AI', status: 'exit-ready', note: 'Approaching IPO readiness. Exit now (certainty premium) or hold for further upside (IRR dilution risk)?' },
                        { name: 'CircleLoop', status: 'strong', note: 'Full commercial partnership with NovaChem generating significant strategic value. Potential acqui-hire target.' }
                    ],
                    events: [
                        { title: 'Co-Founder Crisis', text: 'A portfolio company co-founder has departed after disputes with the CEO. Technology has pivoted twice. The company requests a third bridge round of $1.5M. This is a sunk cost trap — will you write off or double down?' },
                        { title: 'Secondary Market Opportunity', text: 'A PE secondary buyer offers to acquire your positions in two portfolio companies at 15% discount to fair value. Accept (crystallize returns, improve DPI) or decline (preserve upside, maintain strategic positions)?' }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 90700000,
                    totalDeployed: 9300000,
                    portfolioValue: 11439000,
                    moic: 1.23,
                    projectedIRR: 0,
                    svs: 38,
                    financialScore: 0,
                    strategicScore: 0,
                    totalScore: 0,
                    numInvestments: 3,
                    numExits: 0,
                    numWriteOffs: 0,
                    sectorDiversity: 0.4,
                    businessEngagements: 1,
                    acquisitionOptions: 0,
                    portfolioValueHistory: [],
                    financialScoreHistory: [],
                    strategicScoreHistory: [],
                    totalScoreHistory: [],
                    cashHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    ddNewDeals: 50,
                    ddExisting: 30,
                    deal1Amount: 0,
                    deal2Amount: 0,
                    deal3Amount: 0,
                    deal4Amount: 0,
                    followOnAmount: 0,
                    strategicLevel: 1,
                    boardSeat: 'observer'
                };
            }
            // Undo support: the framework's Undo pops the last history row,
            // decrements currentPeriod and re-calls initialize() WITHOUT rolling
            // domainState back. If we hold more snapshots than there are history
            // rows, an Undo just happened -> restore the pre-round domainState so
            // cash / scores / history arrays revert instead of double-counting.
            var histLen = (state.history && state.history.length) || 0;
            if (this._snap && this._snap.length > histLen) {
                state.domainState = this._snap.pop();
            }
            this._updateBriefing(state);
        }

        // Resolve an i18n key through the live framework, falling back to the key.
        _t(key) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    return window.mySimulation.t(key);
                }
            } catch (e) {}
            return key;
        }

        // Localized portfolio-status badge (activates the status_* translations
        // that were previously dead; falls back to the raw upper-cased key).
        _statusLabel(status) {
            var key = 'status_' + String(status).replace(/-/g, '_');
            var label = this._t(key);
            if (label === key) label = String(status).toUpperCase();
            return label;
        }

        validateDecisions(decisions) {
            var ddNew = document.getElementById('ddNewDeals');
            var ddExist = document.getElementById('ddExisting');
            if (ddNew) decisions.ddNewDeals = parseInt(ddNew.value) || 0;
            if (ddExist) decisions.ddExisting = parseInt(ddExist.value) || 0;

            if (decisions.ddNewDeals + decisions.ddExisting > 80) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('dd_warning'), 'warning'
                );
                return false;
            }

            var d1 = document.getElementById('deal1Input');
            var d2 = document.getElementById('deal2Input');
            var d3 = document.getElementById('deal3Input');
            var d4 = document.getElementById('deal4Input');
            if (d1) decisions.deal1Amount = parseFloat(d1.value) || 0;
            if (d2) decisions.deal2Amount = parseFloat(d2.value) || 0;
            if (d3) decisions.deal3Amount = parseFloat(d3.value) || 0;
            if (d4) decisions.deal4Amount = parseFloat(d4.value) || 0;

            var foInput = document.getElementById('followOnInput');
            if (foInput) decisions.followOnAmount = parseFloat(foInput.value) || 0;

            var slInput = document.getElementById('strategicLevel');
            if (slInput) decisions.strategicLevel = parseInt(slInput.value) || 0;

            var bsInput = document.getElementById('boardSeatSelect');
            if (bsInput) decisions.boardSeat = bsInput.value;

            var totalNewInvestment = (decisions.deal1Amount + decisions.deal2Amount + decisions.deal3Amount + decisions.deal4Amount) * 1000000;
            var followOnTotal = decisions.followOnAmount * 1000000;
            var currentCash = window.mySimulation.state.domainState.cash;

            if (totalNewInvestment + followOnTotal > currentCash) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('cash_warning'), 'warning'
                );
                return false;
            }

            var deals = [decisions.deal1Amount, decisions.deal2Amount, decisions.deal3Amount, decisions.deal4Amount];
            for (var i = 0; i < deals.length; i++) {
                if (deals[i] > 0 && (deals[i] < 1 || deals[i] > 12)) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('deal_range_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            // Snapshot the pre-round domainState (serializable) so Undo can roll
            // it back in initialize() instead of re-accumulating on resubmit.
            this._snap.push(JSON.parse(JSON.stringify(ds)));
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var totalNewInvestment = (d.deal1Amount + d.deal2Amount + d.deal3Amount + d.deal4Amount) * 1000000;
            var followOnTotal = d.followOnAmount * 1000000;
            var totalRoundDeploy = totalNewInvestment + followOnTotal;

            ds.cash -= totalRoundDeploy;
            ds.totalDeployed += totalRoundDeploy;

            var newDeals = [d.deal1Amount, d.deal2Amount, d.deal3Amount, d.deal4Amount];
            var investedCount = 0;
            var strategicInvested = 0;
            var totalDealStrategicFit = 0;
            for (var i = 0; i < newDeals.length; i++) {
                if (newDeals[i] > 0) {
                    investedCount++;
                    totalDealStrategicFit += round.deals[i].strategicFit;
                    if (round.deals[i].strategicFit >= 3) {
                        strategicInvested += newDeals[i] * 1000000;
                    }
                }
            }
            ds.numInvestments += investedCount;

            var ddQuality = Math.min(d.ddNewDeals / 60, 1.0);
            var marketMultiplier = 0.85 + Math.random() * 0.35;
            var ddBonus = ddQuality * 0.15;
            var strategicBonus = d.strategicLevel * 0.05;

            var portfolioGrowth = marketMultiplier + ddBonus + strategicBonus;
            ds.portfolioValue = Math.round(ds.portfolioValue * portfolioGrowth + totalNewInvestment * (0.9 + Math.random() * 0.3));

            if (followOnTotal > 0) {
                ds.portfolioValue += Math.round(followOnTotal * (0.8 + Math.random() * 0.6));
            }

            if (ds.totalDeployed > 0) {
                ds.moic = Math.round((ds.portfolioValue / ds.totalDeployed) * 100) / 100;
            }

            var yearsElapsed = state.currentPeriod * 1.5;
            if (ds.moic > 0 && yearsElapsed > 0) {
                ds.projectedIRR = Math.round((Math.pow(ds.moic, 1 / yearsElapsed) - 1) * 10000) / 100;
            }

            var svsGain = 0;
            svsGain += d.strategicLevel * 4;
            svsGain += investedCount > 0 ? (totalDealStrategicFit / investedCount) * 3 : 0;
            if (d.boardSeat === 'seat') svsGain += 3;
            else if (d.boardSeat === 'observer') svsGain += 1;
            svsGain += (d.ddExisting / 30) * 3;
            if (followOnTotal > 0) svsGain += 2;
            ds.svs = Math.min(100, Math.round(ds.svs + svsGain));

            if (d.strategicLevel >= 2) ds.businessEngagements += 1;
            if (d.boardSeat === 'seat') ds.acquisitionOptions += investedCount > 0 ? 1 : 0;

            var sectors = {};
            for (var j = 0; j < newDeals.length; j++) {
                if (newDeals[j] > 0) {
                    var sec = round.deals[j].sector;
                    sectors[sec] = (sectors[sec] || 0) + 1;
                }
            }
            var sectorCount = Object.keys(sectors).length;
            ds.sectorDiversity = Math.min(1.0, ds.sectorDiversity + sectorCount * 0.1);

            var finScore = 0;
            if (ds.projectedIRR >= 20) finScore += 35;
            else if (ds.projectedIRR >= 15) finScore += 30;
            else if (ds.projectedIRR >= 12) finScore += 25;
            else if (ds.projectedIRR >= 8) finScore += 18;
            else finScore += Math.round(ds.projectedIRR * 1.5);

            if (ds.moic >= 2.5) finScore += 25;
            else if (ds.moic >= 1.8) finScore += 20;
            else if (ds.moic >= 1.2) finScore += 12;
            else finScore += Math.max(0, Math.round(ds.moic * 8));

            finScore += Math.round(ds.sectorDiversity * 15);

            var deployRatio = ds.totalDeployed / 100000000;
            var expectedDeploy = state.currentPeriod / 3;
            var disciplineScore = 15 - Math.abs(deployRatio - expectedDeploy * 0.7) * 20;
            finScore += Math.max(0, Math.min(15, Math.round(disciplineScore)));

            finScore += ds.numExits > 0 ? Math.min(10, ds.numExits * 5) : 0;

            ds.financialScore = Math.min(100, Math.max(0, finScore));

            var stratScore = 0;
            stratScore += Math.round(ds.svs * 0.4);
            var alignmentRatio = ds.totalDeployed > 0 ? strategicInvested / ds.totalDeployed : 0;
            stratScore += Math.round(alignmentRatio * 20);
            stratScore += Math.min(15, ds.businessEngagements * 5);
            stratScore += Math.min(15, ds.businessEngagements * 3);
            stratScore += Math.min(10, ds.acquisitionOptions * 3);

            ds.strategicScore = Math.min(100, Math.max(0, stratScore));
            ds.totalScore = ds.financialScore + ds.strategicScore;

            var eventIdx = Math.floor(Math.random() * round.events.length);
            var event = round.events[eventIdx];

            ds.portfolioValueHistory.push(ds.portfolioValue);
            ds.financialScoreHistory.push(ds.financialScore);
            ds.strategicScoreHistory.push(ds.strategicScore);
            ds.totalScoreHistory.push(ds.totalScore);
            ds.cashHistory.push(ds.cash);

            // Advance the briefing / deal panels to the next round SYNCHRONOUSLY.
            // The framework increments currentPeriod right after this returns, so
            // the old deferred setTimeout read the already-incremented period and
            // rendered one round ahead (Round 2 showed Round 3's deals while the
            // scoring still indexed Round 2 -> mis-scoring). Here currentPeriod is
            // still N, so N+1 is correct. Skip on the final round so a spent deal
            // menu is not re-rendered after the game ends.
            if (state.currentPeriod < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }

            // Reveal this round's market event AFTER advancing the briefing:
            // _updateBriefing() hides the event panel, so showing it last keeps it
            // visible for the whole next round instead of flashing for 500 ms.
            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                eventPanel.style.display = 'block';
                eventText.innerHTML = '<b>' + event.title + '</b><br>' + event.text;
            }

            return {
                period: state.currentPeriod,
                roundName: round.title,
                newInvestments: investedCount,
                capitalDeployed: totalRoundDeploy,
                followOnDeployed: followOnTotal,
                portfolioValue: ds.portfolioValue,
                moic: ds.moic,
                projectedIRR: ds.projectedIRR,
                svs: ds.svs,
                financialScore: ds.financialScore,
                strategicScore: ds.strategicScore,
                totalScore: ds.totalScore,
                eventTitle: event.title,
                cash: ds.cash
            };
        }

