        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var totalScore = last.results ? last.results.totalScore || 0 : 0;
            var moic = last.results ? last.results.moic || 0 : 0;
            var irr = last.results ? last.results.projectedIRR || 0 : 0;
            var svs = last.results ? last.results.svs || 0 : 0;

            var performance = 'Developing CVC Manager';
            if (totalScore >= 160 && moic >= 2.0 && svs >= 70) performance = 'Elite CVC Strategist';
            else if (totalScore >= 130 && moic >= 1.8) performance = 'Strong CVC Manager';
            else if (totalScore >= 100) performance = 'Competent CVC Manager';

            var insights = [];
            if (irr >= 15) insights.push('Outstanding financial returns — exceeded the 12% IRR benchmark significantly.');
            else if (irr >= 12) insights.push('Solid financial performance — met the IRR benchmark target.');
            else insights.push('Financial returns fell below the 12% IRR target. Review investment sizing and due diligence allocation.');

            if (svs >= 65) insights.push('Strong strategic value delivery — NovaChem 2030 priorities well served.');
            else if (svs >= 45) insights.push('Moderate strategic value. Deeper business division partnerships could improve outcomes.');
            else insights.push('Low strategic value score. The fund risks being seen as purely financial with limited corporate benefit.');

            if (moic >= 2.5) insights.push('Exceptional MOIC demonstrates excellent capital deployment discipline.');
            else if (moic < 1.5) insights.push('MOIC below 1.5x suggests overvaluation of deals or insufficient portfolio management.');

            return {
                totalScore: totalScore,
                moic: moic,
                projectedIRR: irr,
                svs: svs,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.moic < 1.0) return window.mySimulation.t('hint_low_moic');
            if (results.svs < 40 && state.currentPeriod >= 2) return window.mySimulation.t('hint_low_svs');
            if (results.financialScore > results.strategicScore + 30) return window.mySimulation.t('hint_imbalance_fin');
            if (results.strategicScore > results.financialScore + 30) return window.mySimulation.t('hint_imbalance_strat');
            if (state.domainState.cash < 20000000 && state.currentPeriod < 3) return window.mySimulation.t('hint_low_cash');
            if (results.newInvestments === 0) return window.mySimulation.t('hint_no_invest');
            return null;
        }

