        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = '<b>' + round.title + '</b> (' + round.period + ')<br><br>' + round.briefing;
            }

            var dealPanel = document.getElementById('dealFlowPanel');
            if (dealPanel) {
                var html = '';
                for (var i = 0; i < round.deals.length; i++) {
                    var deal = round.deals[i];
                    var fitStars = '';
                    for (var s = 0; s < 4; s++) {
                        fitStars += s < deal.strategicFit ? '★' : '☆';
                    }
                    var dealInputId = 'deal' + (i + 1) + 'Input';
                    html += '<div class="venture-sim-deal-card">';
                    html += '<h5>' + deal.name + ' <small>(' + deal.stage + ' — ' + this._t('asking_label') + ' $' + (deal.ask / 1000000) + 'M)</small></h5>';
                    html += '<p>' + deal.desc + '</p>';
                    html += '<p><b>' + this._t('fit_label') + ':</b> ' + fitStars + ' | <b>' + this._t('risk_label') + ':</b> ' + deal.financialRisk + '/4</p>';
                    html += '<div class="venture-sim-input-row">';
                    html += '<label for="' + dealInputId + '">' + this._t('invest_label') + '</label>';
                    // step=1: whole-$M tickets. Was 0.5, which let a user enter 0.5
                    // and then fail validateDecisions() ("$1M-$12M or $0"), a dead-end.
                    html += '<input type="number" id="' + dealInputId + '" min="0" max="12" value="0" step="1" data-i18n-placeholder="invest_ph">';
                    html += '</div></div>';
                }
                dealPanel.innerHTML = html;
            }

            var foPanel = document.getElementById('followOnPanel');
            if (foPanel) {
                var foHtml = '';
                for (var j = 0; j < round.portfolioUpdates.length; j++) {
                    var pu = round.portfolioUpdates[j];
                    var statusClass = 'status-good';
                    if (pu.status === 'struggling' || pu.status === 'critical') statusClass = 'status-bad';
                    else if (pu.status === 'early' || pu.status === 'growing') statusClass = 'status-warning';
                    foHtml += '<div class="venture-sim-company-card">';
                    foHtml += '<h5>' + pu.name + ' <span class="' + statusClass + '">(' + this._statusLabel(pu.status) + ')</span></h5>';
                    foHtml += '<p>' + pu.note + '</p>';
                    foHtml += '</div>';
                }
                foHtml += '<div class="venture-sim-input-row">';
                foHtml += '<label for="followOnInput">' + this._t('followon_label') + '</label>';
                foHtml += '<input type="number" id="followOnInput" min="0" max="20" value="0" step="0.5" data-i18n-placeholder="followon_ph">';
                foHtml += '</div>';
                foPanel.innerHTML = foHtml;
            }

            var portfolioPanel = document.getElementById('portfolioPanel');
            if (portfolioPanel) {
                var pHtml = '';
                for (var k = 0; k < round.portfolioUpdates.length; k++) {
                    var pc = round.portfolioUpdates[k];
                    var pcStatusClass = 'status-good';
                    if (pc.status === 'struggling' || pc.status === 'critical') pcStatusClass = 'status-bad';
                    else if (pc.status === 'early' || pc.status === 'growing') pcStatusClass = 'status-warning';
                    else if (pc.status === 'acquisition' || pc.status === 'exit-ready') pcStatusClass = 'status-good';
                    pHtml += '<div class="venture-sim-company-card">';
                    pHtml += '<h5>' + pc.name + ' <span class="' + pcStatusClass + '">(' + this._statusLabel(pc.status) + ')</span></h5>';
                    pHtml += '<p>' + pc.note + '</p>';
                    pHtml += '</div>';
                }
                portfolioPanel.innerHTML = pHtml;
            }

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';
        }
